class TestMinimalProfile(SyncConformance):
    """It cannot make collections, so the suite borrows one that already holds something."""

    def open_backend(self) -> Backend:
        backend = MemoryBackend(profile=MINIMAL)
        backend.store.calendars["default"].put(Task.new(summary="not the suite's").to_ical())
        return backend

    def test_the_borrowed_collection_is_left_as_it_was(self) -> None:
        backend = self.open_backend()
        self._made, self._borrowed = [], []
        collection = self.open_collection(backend)
        before = {i.native_id for i in collection.search()}
        collection.add_task(summary="the suite's")
        self.tidy_up(backend)
        assert {i.native_id for i in collection.search()} == before


class TestFeedProfile(SyncConformance):
    def open_backend(self) -> Backend:
        return MemoryBackend(profile=FEED)

    def seed(self, collection: Collection, items: Sequence[Item]) -> list[SyncItem]:
        assert isinstance(collection, MemoryBackend.collection_class)
        native_ids = [collection.store.put(item.to_ical()) for item in items]
        return [collection.get_by_native_id(n) for n in native_ids]
